import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Explicit !!int with a signed binary literal must still resolve.
    assert.strictEqual(load('!!int "-0b101"'), -5);
    // And unsigned explicit binary still works.
    assert.strictEqual(load('!!int "0b101"'), 5);
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Explicitly tagged signed octal integers must resolve under CORE_SCHEMA;
    // the original explicit pattern allowed an optional sign before "0o".
    assert.strictEqual(load('!!int "+0o17"', { schema: require('js-yaml').CORE_SCHEMA ?? undefined }), 15);
  });
});

